using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace FontFilter;
public sealed class TagPickerWindow:Window
{
 readonly List<(TagDefinition Definition,CheckBox Box)> options=new();
 public bool UseForSearch{get;private set;}
 public IEnumerable<string> SelectedTags=>options.Where(x=>x.Box.IsChecked==true).Select(x=>x.Definition.Name);
 public TagPickerWindow(IReadOnlyList<TagDefinition>? definitions=null,IReadOnlyDictionary<string,int>? counts=null){var tags=definitions??TagCatalog.All;LightTheme.Apply(this);Title="字体标签库";Width=880;Height=720;MinWidth=650;MinHeight=450;WindowStartupLocation=WindowStartupLocation.CenterOwner;FontFamily=new FontFamily("Microsoft YaHei UI");Background=new SolidColorBrush(Color.FromRgb(247,248,250));FontSize=13;
  var dock=new DockPanel{Margin=new Thickness(24)};Content=dock;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);dock.Children.Add(top);top.Children.Add(new TextBlock{Text=$"{tags.Count} 个标签 · {tags.Select(t=>t.Category).Distinct().Count()} 个维度",FontSize=22,FontWeight=FontWeights.Bold});top.Children.Add(new TextBlock{Text="数字为本地匹配家族数，灰色表示无匹配。多选标签需同时匹配；使用本次选择会替换旧筛选。",Margin=new Thickness(0,8,0,12),TextWrapping=TextWrapping.Wrap,Foreground=Brushes.DimGray});var search=new TextBox{Padding=new Thickness(10),Margin=new Thickness(0,0,0,12)};top.Children.Add(search);
  var bottom=new DockPanel{Margin=new Thickness(0,16,0,0)};DockPanel.SetDock(bottom,Dock.Bottom);dock.Children.Add(bottom);var state=new TextBlock{Text="已选0项",VerticalAlignment=VerticalAlignment.Center};bottom.Children.Add(state);var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};bottom.Children.Add(actions);
  void Finish(bool useForSearch){if(!SelectedTags.Any()){state.Text="请先选择标签";return;}UseForSearch=useForSearch;DialogResult=true;}
  var searchAction=new Button{Content="使用本次筛选",Padding=new Thickness(14,8,14,8),Margin=new Thickness(0,0,8,0)};searchAction.Click+=(_,_)=>Finish(true);actions.Children.Add(searchAction);var tagAction=new Button{Content="填入人工标签框",Padding=new Thickness(14,8,14,8)};tagAction.Click+=(_,_)=>Finish(false);actions.Children.Add(tagAction);
  var body=new StackPanel();dock.Children.Add(new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var categories=new List<(StackPanel Panel,List<CheckBox> Boxes)>();
  foreach(var category in tags.GroupBy(x=>x.Category)){var group=new StackPanel{Margin=new Thickness(0,0,0,16)};group.Children.Add(new TextBlock{Text=category.Key,FontSize=16,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});var wrap=new WrapPanel();group.Children.Add(wrap);var boxes=new List<CheckBox>();foreach(var def in category){var label=new Grid{Width=120};label.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(82)});label.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(38)});label.Children.Add(new TextBlock{Text=def.Name,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis});var number=new TextBlock{Text=counts==null?"":$"({counts.GetValueOrDefault(def.Name)})",VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Right};Grid.SetColumn(number,1);label.Children.Add(number);var box=new CheckBox{Content=label,Width=150,Height=34,VerticalContentAlignment=VerticalAlignment.Center,Foreground=counts!=null&&counts.GetValueOrDefault(def.Name)==0?Brushes.Gray:Brushes.DarkSlateGray,Opacity=counts!=null&&counts.GetValueOrDefault(def.Name)==0?0.45:1,Padding=new Thickness(2,0,0,0),Margin=new Thickness(0,0,8,6),ToolTip=def.Name+"\n识别词："+def.Aliases.Replace('|','、')};System.Windows.Automation.AutomationProperties.SetName(box,def.Name);box.Checked+=(_,_)=>state.Text=$"已选{SelectedTags.Count()}项";box.Unchecked+=(_,_)=>state.Text=$"已选{SelectedTags.Count()}项";options.Add((def,box));boxes.Add(box);wrap.Children.Add(box);}body.Children.Add(group);categories.Add((group,boxes));}
  search.TextChanged+=(_,_)=>{var q=search.Text.Trim();foreach(var entry in options)entry.Box.Visibility=q.Length==0||entry.Definition.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||entry.Definition.Category.Contains(q,StringComparison.OrdinalIgnoreCase)||entry.Definition.Aliases.Contains(q,StringComparison.OrdinalIgnoreCase)?Visibility.Visible:Visibility.Collapsed;foreach(var category in categories)category.Panel.Visibility=category.Boxes.Any(b=>b.Visibility==Visibility.Visible)?Visibility.Visible:Visibility.Collapsed;};
 }
}
